export { mataUang } from './format.js';
// === main.js ===
import rp, { mataUang as kode } from './format.js';
import * as harga from './harga.js';
console.log(rp(harga.daftar.kopi));
console.log(kode, harga.mataUang);
console.log(Object.keys(harga));

